class Ability {
public:
  virtual ~Ability() {}
protected:
  virtual void activate() = 0;            // sandbox method

  // Provided operations (non-virtual).
  void playSound(SoundId id, float volume);
  void spawnParticles(ParticleType type, int count);
  void applyKnockback(Unit& target, float force);
  void impactFeedback(Unit& target, float force) {  // rolled-up helper
    applyKnockback(target, force);
    shakeCamera(force * 0.1f);
    playSound(SOUND_IMPACT, 1.0f);
  }
  void shakeCamera(float amount);
};

class GroundSlam : public Ability {
protected:
  virtual void activate() {
    for (Unit* u : enemiesInRadius(300))
      impactFeedback(*u, 500);
    spawnParticles(PARTICLE_DUST, 40);
  }
};

class Ability {
protected:
  virtual void activate() = 0;

  SoundPlayer& sound()  { return *sound_; }
  FxPlayer&    fx()     { return *fx_; }
  CombatOps&   combat() { return *combat_; }

  // Deprecated: forwards during migration.
  void playSound(SoundId id, float v) { sound().play(id, v); }

private:
  SoundPlayer* sound_;   // forward-declared in Ability.h
  FxPlayer*    fx_;
  CombatOps*   combat_;
};

class Dash : public Ability {
protected:
  virtual void activate() {
    if (isGrounded()) {
      playSound(SOUND_DASH, 1.0f);
      spawnParticles(PARTICLE_DUST, 10);
      move(facing() * 8, 0);
    } else if (getHeroHeight() < 3) {
      playSound(SOUND_SWOOP, 1.0f);
      move(facing() * 5, -getHeroHeight());
    } else {
      playSound(SOUND_DIVE, 0.7f);
      setOnLand([this] { spawnShockwave(4); });
      move(0, -getHeroHeight());
    }
  }
};

class DataDrivenAbility : public Ability {
public:
  explicit DataDrivenAbility(const AbilityDef& def) : def_(def) {}
protected:
  virtual void activate() {
    playSound(def_.sound, def_.volume);
    spawnParticles(def_.particle, def_.particleCount);
    healHero(def_.healAmount);
  }
private:
  AbilityDef def_;
};

class UnitAbility {
protected:
  virtual void activate() = 0;

  float getTerrainHeight(int x, int y) const;   // (a) read-only, widely used
  Unit* spawnUnit(UnitType type, Vec2 pos);     // (c) mutates state: centralize
  void  playSound(SoundId id, float vol) {      // (d) forwarding, but hides field
    soundEngine_.play(id, vol);
  }
  int   simTick() const;                        // (e') deterministic time
  int   rng(int max);                           // seeded, in sync on all peers

private:
  SoundEngine& soundEngine_;
};

class UnitAbility {
public:
  struct Systems { ParticleSystem* particles; SoundEngine* sound;
                   World* world; NetSync* net; };
  static void init(const Systems& s) { systems_ = s; }  // once at startup
  virtual ~UnitAbility() {}
protected:
  virtual void activate() = 0;
  void spawnParticles(ParticleType t, int n) {
    systems_.particles->spawn(t, n);
  }
private:
  static Systems systems_;
};

class FireBall : public UnitAbility {   // no constructor plumbing needed
protected:
  virtual void activate() { spawnParticles(PARTICLE_FIRE, 20); }
};
